def fizzbuzz(n: int) -> str:
    """Retorna Fizz, Buzz, FizzBuzz o el número."""
    if n % 15 == 0:
        return "FizzBuzz"
    if n % 3 == 0:
        return "Fizz"
    if n % 5 == 0:
        return "Buzz"
    return str(n)

